// Minimal standard entry point (C99 and later)
int main(void) {
    return 0; // EXIT_SUCCESS
}

// Entry point receiving command line arguments
// argc: count of arguments
// argv: array of string arguments (char*)
int main(int argc, char *argv[]) {
    /* Code block execution starts here */

    if (argc < 2) return 1; // EXIT_FAILURE

    /* argv[0] is the program name */
    return 0;
}

// Standard return values: 0 (Success), Non-zero (Error)
